let workflowSignature='',workflowSnapshot=null,selectedReferenceIds=new Set(),scanPreviews=[];
const fileCorrections=new WeakMap();
function correctionsForFiles(selected){return selected.flatMap((file,i)=>fileCorrections.has(file)?[{fileIndex:i,...fileCorrections.get(file)}]:[]);}
function protectionApproval(){return {confirmUnlock:$('#protect-unlock').checked,unlockIds:[...document.querySelectorAll('[data-unlock-id]:checked')].map(el=>el.dataset.unlockId)};}
function element(tag,text='',className=''){return textElement(tag,text,className);}
function renderWorkflow(snapshot){workflowSnapshot=snapshot;const signature=JSON.stringify([snapshot.jobId,snapshot.version,snapshot.protectedFields,snapshot.checks,snapshot.regions,snapshot.proposal,snapshot.preflight,snapshot.references]);const blocked=snapshot.busy||Boolean(snapshot.proposal)||snapshot.hasQuestions;
 for(const selector of ['#direct-save','#protect-save','#region-add'])$(selector).disabled=blocked;
 if(signature===workflowSignature)return;const versionChanged=!workflowSignature||snapshot.jobId!==$('#direct-text').dataset.jobId||String(snapshot.version)!==$('#direct-text').dataset.version;workflowSignature=signature;
 if(versionChanged&&inspectResult){$('#direct-text').value=inspectResult.text;$('#direct-text').dataset.jobId=snapshot.jobId;$('#direct-text').dataset.version=snapshot.version;$('#protect-unlock').checked=false;window.resetStructuredEditor?.();}
 const draftFields=new Map([...document.querySelectorAll('[data-direct-id]')].map(e=>[e.dataset.directId,e.value])),draftRegions=new Map([...document.querySelectorAll('[data-region-edit]')].map(e=>[e.dataset.regionEdit,e.value]));
 const fields=(snapshot.fields||[]).map(field=>{const row=element('div','','direct-field'),label=element('label',field.label),input=document.createElement('input');input.dataset.directId=field.id;input.value=!versionChanged&&draftFields.has(field.id)?draftFields.get(field.id):field.translated;input.maxLength=2000;input.disabled=blocked;label.append(input);const save=element('button','Feld korrigieren','secondary');save.disabled=blocked;save.onclick=()=>void inspectorTask(()=>localRequest(`/api/jobs/${reviewJobId}/direct`,{version:reviewData.version,fieldEdits:[{id:field.id,translated:input.value}],...protectionApproval()}));row.append(label,save);return row;});$('#direct-fields').replaceChildren(...fields);
 $('#protected-fields').replaceChildren(...(snapshot.fields||[]).map(field=>{const label=element('label'),check=document.createElement('input');check.type='checkbox';check.dataset.protectId=field.id;check.checked=snapshot.protectedFields.some(f=>f.id===field.id);check.disabled=blocked||!snapshot.checks.some(c=>c.id===field.id&&c.confirmed)&&!check.checked;label.append(check,document.createTextNode(field.label+' · '+field.translated));return label;}));
 $('#unlock-fields').replaceChildren(...snapshot.protectedFields.map(field=>{const label=element('label'),check=document.createElement('input');check.type='checkbox';check.dataset.unlockId=field.id;label.append(check,document.createTextNode(field.label+' bewusst zur Änderung freigeben'));return label;}));
 if(snapshot.proposal?.protectedConflicts?.length)$('#revision-changes').prepend(element('p','Geschützte Angaben betroffen: '+snapshot.proposal.protectedConflicts.map(f=>f.label).join(', ')+'. In „Direkt korrigieren“ die betroffenen Felder ausdrücklich zur Änderung freigeben oder diese Änderungen abwählen.','audit-warning'));
 $('#special-regions').replaceChildren(...(snapshot.regions||[]).map(region=>{const row=element('div','','region-row');row.append(element('strong',region.label),element('p','Original: '+region.source));const label=element('label','Übersetzte Beschreibung'),input=document.createElement('textarea');input.rows=2;input.maxLength=2000;input.dataset.regionEdit=region.id;input.value=!versionChanged&&draftRegions.has(region.id)?draftRegions.get(region.id):region.translated;input.disabled=blocked;label.append(input);const locate=element('button','Originalausschnitt ansehen','text-button');locate.onclick=()=>focusField(region);const save=element('button','Bereich korrigieren','secondary');save.disabled=blocked;save.onclick=()=>void inspectorTask(()=>localRequest(`/api/jobs/${reviewJobId}/direct`,{version:reviewData.version,regionEdits:[{id:region.id,translated:input.value}],...protectionApproval()}));const state=element('p',snapshot.checks.some(c=>c.id===region.id&&c.confirmed)?'Am Original bestätigt':'Noch im Bereich „Prüffelder“ bestätigen','muted');row.append(label,locate,save,state);return row;}));if(!snapshot.regions?.length)$('#special-regions').append(element('p','Keine besonderen Bereiche automatisch erfasst. Das gesamte Original trotzdem nach Stempeln und Handschrift durchsuchen.','muted'));
 $('#used-references').replaceChildren(...(snapshot.references||[]).map(ref=>{const details=document.createElement('details');details.className='used-reference';const title=[ref.name,ref.documentType].filter(Boolean).join(' · '),count=Number.isSafeInteger(ref.matchedLineCount)&&ref.matchedLineCount>0,summary=count?'Wörtliche Übereinstimmungen erkannt: {count}':'Als Kontext berücksichtigt; keine wörtliche Übereinstimmung erkannt.',description=window.TOCRI18n?.t(summary)||summary;details.append(element('summary',title||window.TOCRI18n?.t('Referenz')||'Referenz'),element('p',description.replace('{count}',String(ref.matchedLineCount||0))));if(ref.structure)details.append(element('p',window.TOCRI18n?.t('Strukturhinweis')+': '+ref.structure,'muted'));return details;}));if(!snapshot.references?.length)$('#used-references').append(element('p',window.TOCRI18n?.t('Für diese Fassung wurden keine freigegebenen Beispiele verwendet.')||'Für diese Fassung wurden keine freigegebenen Beispiele verwendet.','muted'));
 $('#region-count').textContent=snapshot.regions?.length?'· '+snapshot.regions.length+' erkannt':'';if(snapshot.proposal)document.querySelector('.revision-card').open=true;renderPreflight(snapshot.preflight);
}
function renderPreflight(report){const host=$('#preflight-report');host.replaceChildren();if(!report){host.append(element('p','Ältere Ausgabe: nach einer neuen Korrektur ist die technische Druckkontrolle verfügbar.'));return;}const pageSummary='{translations} Übersetzungsseite(n) · {pages} PDF-Seiten insgesamt';host.append(element('p',(window.TOCRI18n?.t(pageSummary)||pageSummary).replace('{translations}',String(report.translationPages)).replace('{pages}',String(report.pageCount))));for(const issue of [...report.issues,...report.browserIssues])host.append(element('p',(issue.page?'Seite '+issue.page+': ':'')+issue.message,'audit-warning'));if(!report.issues.length&&!report.browserIssues.length)host.append(element('p',window.TOCRI18n?.t('Bisher keine technischen Auffälligkeiten gemeldet. PDF-Seitenprüfung und Sichtprüfung bleiben erforderlich.')||'Bisher keine technischen Auffälligkeiten gemeldet. PDF-Seitenprüfung und Sichtprüfung bleiben erforderlich.','muted'));}
$('#direct-save').onclick=()=>void inspectorTask(()=>localRequest(`/api/jobs/${reviewJobId}/direct`,{version:reviewData.version,...(window.directEditPayload?.()||{text:$('#direct-text').value}),...protectionApproval()}));
$('#protect-save').onclick=()=>void inspectorTask(()=>localRequest(`/api/jobs/${reviewJobId}/protect`,{version:reviewData.version,ids:[...document.querySelectorAll('[data-protect-id]:checked')].map(el=>el.dataset.protectId),confirmUnlock:$('#protect-unlock').checked}));
$('#region-add').onclick=()=>void inspectorTask(()=>{const box=$('#region-box').value.trim();return localRequest(`/api/jobs/${reviewJobId}/direct`,{version:reviewData.version,regionAdd:{label:$('#region-label').value||'Ergänzter Bereich',kind:$('#region-kind').value,source:$('#region-source').value,translated:$('#region-translation').value,fileIndex:Number($('#region-file').value),page:Number($('#region-page').value),box:box?box.split(',').map(Number):null},...protectionApproval()});});
window.addEventListener('translateocr-locale',()=>{if(workflowSnapshot){workflowSignature='';renderWorkflow(workflowSnapshot);renderPreflight(workflowSnapshot.preflight);}});
$('#preflight-run').onclick=()=>void inspectorTask(async()=>{if(!pdfDocument||!workflowSnapshot?.preflight)throw new Error('Bitte warten, bis die aktuelle PDF-Vorschau geladen ist.');const id=reviewJobId,version=reviewData.version,report=workflowSnapshot.preflight,doc=pdfDocument,issues=[];const {auditTextPage}=await import('/layout-audit.mjs');for(let i=1;i<=Math.min(report.translationPages,150);i++){const page=await doc.getPage(i),viewport=page.getViewport({scale:1}),content=await page.getTextContent();issues.push(...auditTextPage(content.items,viewport,i));}if(id!==reviewJobId||version!==reviewData.version)throw new Error('Die Fassung wurde inzwischen geändert.');await localRequest(`/api/jobs/${id}/preflight`,{version,digest:report.digest,issues});toast('Technische PDF-Seitenprüfung abgeschlossen. Umbrüche zusätzlich visuell prüfen.');});
let scanCropRect=null,scanCropCanvas=null,scanPage=1,scanPageCount=1;
async function drawScanCrop(){
 const stage=$('#scan-crop-stage'),index=Number($('#scan-file').value),source=scanPreviews[index],imageSource=Boolean(source?.type?.startsWith('image/')),instructions=$('.scan-preview-label span');
 stage.replaceChildren();if(!source)return;const saved=fileCorrections.get(files[index])||{};scanCropRect=imageSource?(saved.crop||null):(saved.crops?.[scanPage]||null);
 const {canvas,pages}=await sourceCanvas(source,scanPage);scanCropCanvas=canvas;scanPageCount=pages;$('#scan-pdf-page-label').hidden=imageSource||pages<2;$('#scan-pdf-page').replaceChildren(...Array.from({length:pages},(_,i)=>new Option(`${i+1} / ${pages}`,String(i+1))));$('#scan-pdf-page').value=String(Math.min(scanPage,pages));canvas.className='scan-crop-image';canvas.tabIndex=0;canvas.setAttribute('role','group');
 const cropInstructions='Rahmen ziehen oder Bild fokussieren: Eingabetaste setzt einen mittigen Zuschnitt · Pfeiltasten verschieben · Umschalt + Pfeiltasten ändern die Größe · Entf löscht.';
 canvas.setAttribute('aria-label',window.TOCRI18n.t('Zuschnitt. Eingabetaste setzt einen mittigen Rahmen. Pfeiltasten verschieben; Umschalt plus Pfeiltasten ändern die Größe. Entf löscht den Rahmen.'));
 if(instructions)instructions.textContent=window.TOCRI18n.t(cropInstructions);
 const frame=document.createElement('div');frame.className='scan-crop-frame';frame.append(canvas);const selection=document.createElement('div');selection.className='scan-crop-selection';selection.setAttribute('aria-hidden','true');frame.append(selection);stage.append(frame);
 function paint(){if(!scanCropRect){selection.hidden=true;return}selection.hidden=false;selection.style.left=`${scanCropRect[0]*100}%`;selection.style.top=`${scanCropRect[1]*100}%`;selection.style.width=`${scanCropRect[2]*100}%`;selection.style.height=`${scanCropRect[3]*100}%`}
 function announceCrop(){const status=$('#scan-crop-status');if(!scanCropRect)status.textContent=window.TOCRI18n.t('Kein Zuschnitt ausgewählt.');else status.textContent=window.TOCRI18n.t('Zuschnitt ausgewählt.')+' '+Math.round(scanCropRect[2]*100)+'% × '+Math.round(scanCropRect[3]*100)+'%'}
 {let start=null;const point=e=>{const r=canvas.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))]};canvas.onkeydown=e=>{if(!['Enter','Delete','Backspace','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const key=e.shiftKey&&e.key.startsWith('Arrow')?'Shift+'+e.key:e.key,step=e.shiftKey?.05:.01,next=window.adjustCropRect(scanCropRect,key,step);if(next===scanCropRect)return;scanCropRect=next;paint();announceCrop()};canvas.onpointerdown=e=>{if(e.button!==0)return;canvas.focus();canvas.setPointerCapture(e.pointerId);start=point(e);scanCropRect=[start[0],start[1],0,0];paint();announceCrop()};canvas.onpointermove=e=>{if(!start)return;const end=point(e),x=Math.min(start[0],end[0]),y=Math.min(start[1],end[1]);scanCropRect=[x,y,Math.abs(end[0]-start[0]),Math.abs(end[1]-start[1])];paint()};canvas.onpointerup=()=>{start=null;if(scanCropRect&&scanCropRect[2]<.025&&scanCropRect[3]<.025)scanCropRect=null;paint();announceCrop()};}
 paint();announceCrop();
}
$('#scan-file').onchange=()=>{scanPage=1;void drawScanCrop();};
$('#scan-pdf-page').onchange=()=>{scanPage=Number($('#scan-pdf-page').value)||1;void drawScanCrop();};
$('#scan-analyze').onclick=()=>void workspaceTask(async()=>{if(!files.length)throw new Error('Bitte zuerst Dateien auswählen.');const selectedIndex=Number($('#scan-file').value)||0,selected=[...files],data=await localRequest('/api/scan',{files:await documentsForRequest(selected)}).then(r=>r.json());if(!selected.every((f,i)=>files[i]===f))throw new Error('Dateiauswahl wurde inzwischen geändert.');scanPreviews=data.previews;$('#scan-file').replaceChildren(...selected.map((f,i)=>(()=>{const option=new Option(f.name,i);option.dataset.noTranslate='';return option;})()));$('#scan-file').value=String(Math.min(selectedIndex,selected.length-1));$('#scan-reports').replaceChildren(...data.files.map(report=>{const box=element('div'),reportName=element('strong',report.name);reportName.dataset.noTranslate='';box.append(reportName,element('p',report.warnings.length?report.warnings.join(' '):'Keine heuristische Auffälligkeit. Ränder und Spiegelungen visuell prüfen.','muted'));if(report.orientation&&report.orientation!==1)box.append(element('p','EXIF-Ausrichtung wird bei der Verarbeitung berücksichtigt.'));return box;}));await drawScanCrop();if($('#scan-dialog').dataset.focusCropOnReady==='true'){delete $('#scan-dialog').dataset.focusCropOnReady;if(matchMedia('(max-width: 599px)').matches)requestAnimationFrame(()=>$('#scan-crop-stage').scrollIntoView({block:'center',behavior:'instant'}));}});
$('#scan-preview').onclick=()=>void workspaceTask(async()=>{const index=Number($('#scan-file').value),file=files[index];if(!file)throw new Error('Bitte Dateiauswahl zuerst prüfen.');const previous=fileCorrections.get(file)||{},correction=file.type==='application/pdf'?{...previous,rotation:Number($('#scan-rotation').value),crops:{...(previous.crops||{}),...(scanCropRect?{[scanPage]:scanCropRect}:{})}}:{...previous,rotation:Number($('#scan-rotation').value),crop:scanCropRect};const result=await localRequest('/api/scan/correct',{file:{name:file.name,type:file.type,data:await fileBase64(file)},...correction}).then(r=>r.json());const {canvas}=await sourceCanvas(result,scanPage);if(files[index]!==file)throw new Error('Dateiauswahl wurde inzwischen geändert.');canvas.setAttribute('role','img');canvas.setAttribute('aria-label','Korrigierte Arbeitskopie');$('#scan-working-preview').replaceChildren(canvas,element('p','Diese Arbeitskopie ist für den nächsten Auftrag vorgemerkt. Das Original bleibt unverändert.','muted'));fileCorrections.set(file,correction);});
$('#scan-reset').onclick=()=>{const file=files[Number($('#scan-file').value)];if(file)fileCorrections.delete(file);$('#scan-working-preview').replaceChildren();scanCropRect=null;scanPage=1;$('#scan-rotation').value='0';drawScanCrop();toast('Arbeitskopie zurückgesetzt.');};
